    {"claim": "Priya's mug is at the kitchen table at 8:00 on a weekday for her morning tea", "target": "mug_priya", "expect": "kitchen_table_k1", "days": "weekday", "from": 7, "to": 9},
    {"claim": "Priya's bowl is back at the sink by 16:00 on a weekday", "target": "bowl_priya", "expect": "sink_k1", "days": "weekday", "from": 15, "to": 18},
    {"claim": "Priya's mug is at the sink by 16:00 on a weekday", "target": "mug_priya", "expect": "sink_k1", "days": "weekday", "from": 15, "to": 18}
